let arcTrip=null,arcPrevious={key:'',value:0};
const arcDepartureBase=departureChoice;departureChoice=function(m){if(arcTrip&&arcTrip.route===arrivalRoute&&arcTrip.direction===arrivalDirection&&arcTrip.board===arrivalBoard)return {v:arcTrip.vehicle,t:arcTrip.vehicle.times.find(t=>t.stopId===arrivalBoard)};return arcDepartureBase(m)};
function arcState(){let m=arrivalModel(),choice=departureChoice(m),riding=!!arcTrip&&arcTrip.route===arrivalRoute&&arcTrip.direction===arrivalDirection&&arcTrip.board===arrivalBoard,p=choice?MetroProgress.journeyProgress(choice.v.times,m.now,arrivalBoard,riding,m.ids.at(-1)):{fraction:0,remaining:null,phase:'unavailable'};return {m,choice,riding,...p}}
function boardArcBus(){let a=arcState();if(!a.choice)return;arcTrip={route:arrivalRoute,direction:arrivalDirection,board:arrivalBoard,vehicle:a.choice.v};arrivalTime=Math.max(arrivalTime,a.choice.t.expectedDeparture);arrivalBus=a.choice.v.number;closeModal();render();toast('Demo ride started. Following the same bus to your destination.')}
function finishArcRide(){arcTrip=null;closeModal();render()}
function arcProgressDetails(){let a=arcState();modal('Your journey progress',`<div class="progress-phase-tabs"><span class="${!a.riding?'active':''}">1 · Bus to your stop</span><span class="${a.riding?'active':''}">2 · Your ride</span></div><h2>${a.phase==='arrived'?'You’ve arrived':a.riding?'On your way':a.phase==='at-stop'?'Your bus is here':'Your bus is approaching'}</h2><p class="sub" style="margin:12px 0 20px">${a.riding?safe(stopName(arrivalBoard))+' → '+safe(stopName(a.m.ids.at(-1))):safe(stopName(a.m.ids[0]))+' → '+safe(stopName(arrivalBoard))}</p><div class="progress-detail-number">${Math.round(a.fraction*100)}% <small>complete · demo position</small></div><p class="tiny">${a.riding?'The same bus stays selected throughout your ride.':'The filled arc follows the bus from its route origin to your boarding stop.'}</p>${a.riding?`<button class="primary full" style="margin-top:20px" onclick="finishArcRide()">${a.phase==='arrived'?'Finish journey':'End demo ride'}</button>`:`<button class="primary full" style="margin-top:20px" onclick="boardArcBus()" ${!a.choice?'disabled':''}>${ic('bus')}Board demo bus</button>`}<button class="secondary full" style="margin-top:10px" onclick="arrivalTime+=3;render();arcProgressDetails()">Advance demo by 3 min</button><p class="tiny" style="margin-top:15px">Temporary simulation. Boarding early moves the demo clock to your bus’s departure time.</p>`)}
function interactiveArc(a){let pct=a.fraction*100,key=arrivalRoute+'|'+arrivalDirection+'|'+arrivalBoard+'|'+a.riding+'|'+a.choice?.v.number,previous=arcPrevious.key===key?arcPrevious.value:pct;arcPrevious={key,value:pct};let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,dur=reduced?'0.001s':'.8s',path='M20 104C35 -10 285 -10 300 104';return `<button class="journey-dome progress-dome" onclick="arcProgressDetails()" aria-label="${a.riding?'Your ride':'Bus approaching'}: ${Math.round(pct)} percent complete. View journey progress"><svg viewBox="0 0 320 125" aria-hidden="true"><path class="progress-track" d="${path}"/><path class="progress-fill" d="${path}" pathLength="100" stroke-dasharray="${pct} 100"><animate attributeName="stroke-dasharray" from="${previous} 100" to="${pct} 100" dur="${dur}" fill="freeze"/></path><circle cx="20" cy="104" r="4.5" class="progress-end"/><path class="progress-terminal-arrow" d="m291 97 9 9 7-11"/><g class="progress-vehicle"><animateMotion path="${path}" keyPoints="${previous/100};${a.fraction}" keyTimes="0;1" calcMode="linear" dur="${dur}" fill="freeze"/><circle r="13" class="progress-halo"/><circle r="10" fill="var(--journey-color)" stroke="white" stroke-width="2"/><use href="#i-bus" x="-6" y="-6" width="12" height="12" stroke="white" fill="none" stroke-width="1.8"/></g></svg><span class="dome-time"><b>${a.remaining===null?'-':a.remaining}<small>${a.remaining===null?'':' min'}</small></b><span>${a.phase==='arrived'?'You’ve arrived':a.riding?'To your destination':a.phase==='at-stop'?'Bus at your stop':'Until your bus arrives'}</span></span><span class="arc-phase-label">${a.riding?'2 · Your ride':'1 · Bus to your stop'} <span>${Math.round(pct)}%</span></span></button>`}
const progressHeroBase=arrivalHero;arrivalHero=function(){let a=arcState(),html=progressHeroBase(),left=a.riding?stopName(arrivalBoard):stopName(a.m.ids[0]),right=a.riding?stopName(a.m.ids.at(-1)):stopName(arrivalBoard);html=html.replace(/<div class="journey-dome"[\s\S]*?<div class="dome-endpoints">/,interactiveArc(a)+'<div class="dome-endpoints">');html=html.replace(/<div class="dome-endpoints">[\s\S]*?<\/div>/,`<div class="dome-endpoints progress-endpoints"><b>${safe(left)}</b><button onclick="${a.riding?'arcProgressDetails()':'switchArrivalDirection();rememberBoarding()'}" aria-label="${a.riding?'View ride details':'Reverse journey direction'}">${a.riding?ic('bus'):'⇄'}</button><b>${safe(right)}</b></div>`);html=html.replace('<div class="arc-arrival-summary">',`<button class="arc-boarding-action" onclick="${a.riding?'arcProgressDetails()':'boardArcBus()'}">${ic(a.riding?'bus':'check')}${a.riding?(a.phase==='arrived'?'You’ve arrived · finish journey':'On board · view progress'):'I’m on board · start demo ride'}${ic('arrow')}</button><div class="arc-arrival-summary">`);if(a.riding)html=html.replace('NEXT AT YOUR STOP','YOUR RIDE').replace(/<strong>[^<]*<\/strong>/,`<strong>${a.phase==='arrived'?'Arrived':a.remaining+' min'}</strong>`).replace(/<span>Arrives [^<]*<\/span>/,`<span>To ${safe(stopName(a.m.ids.at(-1)))}</span>`);return html};
render();
